  dict(q="Systems help because they:", o=["Keep working in busy seasons", "Require constant willpower", "Guarantee returns"], a=0, why="Habits outlast motivation."),
  dict(q="The great wealth destroyers include:", o=["Excessive debt and concentration", "Diversification", "Saving"], a=0, why="Avoid the few big mistakes."),
  dict(q="Proverbs 11:14 teaches that safety comes from:", o=["A multitude of counsellors", "Acting alone", "Secrecy"], a=0, why="Wise counsel protects."),
  dict(q="Deuteronomy 8:18 says God gives power to get wealth to:", o=["Establish His covenant", "Build pride", "Hoard"], a=0, why="Wealth serves His purposes."),
  dict(q="An ownership review lists:", o=["What you own that grows or produces income", "Only your bills", "Your salary history"], a=0, why="It reveals your asset base."),
  dict(q="Kingdom builders hold wealth:", o=["With open hands", "With clenched fists", "Secretly"], a=0, why="Wealth is entrusted, not owned forever."),
  dict(q="Which is an income-producing asset?", o=["A rental property", "A new car", "A vacation"], a=0, why="It can produce ongoing income."),
