L['kingdom-1'] = dict(deep=True, mins=15,
 intro="At the Kingdom Builder level, tax planning becomes one of the most powerful tools for preserving wealth. These strategies are legal, widely used, and built into the tax code. Used wisely, with a qualified professional, they can keep far more of your wealth working for your family and your mission.",
 connect="Every dollar kept from unnecessary tax can fund your why and your giving.",
 sections=[
  ["Asset location", ["Different accounts are taxed differently, so where you hold each investment matters. Many investors place tax-inefficient investments, such as bonds and REITs, in tax-deferred accounts, and tax-efficient index funds in taxable accounts. Roth accounts are often used for investments with the highest growth potential."]],
  ["Roth conversions", ["Converting money from a traditional IRA to a Roth IRA means paying tax now so future qualified withdrawals are tax-free. Conversions are often considered in years when income is lower, such as early retirement or a business transition."]],
  ["Giving appreciated investments", ["Donating stock or funds you have held more than a year, instead of cash, can let you deduct the full market value (subject to limits) and avoid capital gains tax on the growth. Donor-advised funds make this simple."]],
  ["Gifts and the estate", ["In 2026, you can give up to $19,000 per person each year without using any of your lifetime exemption, and the federal estate and gift tax exemption is $15 million per person. Assets inherited at death generally receive a step-up in cost basis, which can erase capital gains built up during life."]],
  ["Business and retirement strategies", ["Business owners may use retirement plans such as a Solo 401(k), SEP IRA, or defined benefit plan to save more before tax, and should choose an entity structure with a CPA. Health savings accounts, when eligible, offer tax benefits on contributions, growth, and qualified withdrawals.",
    "\"Render therefore unto Caesar the things which are Caesar's\" (Matthew 22:21): pay what is owed, and steward the rest."]],
 ],
 pros=["Preserves more wealth for family and mission", "Uses legal strategies in the tax code", "Can increase charitable impact", "Coordinates investing, giving, and estate plans"],
 cons=["Rules are complex and change often", "Mistakes can be costly", "Requires qualified professional help", "Some strategies have strict deadlines and limits"],
 watch=["Tax laws change; verify current figures every year.", "Work with a qualified CPA or tax attorney.", "Be wary of promoters selling aggressive tax shelters.", "Document everything carefully."],
 tip="Ask your CPA for a \"tax projection\" in October, not just a tax return in April. Planning before year-end opens strategies, such as Roth conversions and charitable gifts, that disappear on December 31.",
 fit=dict(starter="Roth contributions while your rate is lower can be valuable.", mom="Use 529 plans and annual gifts thoughtfully.", rebuilder="Review filing status and cost basis on assets you received.", ent="Coordinate entity choice and retirement plans with your CPA.", exec="Plan for taxes on equity compensation.", late="Consider catch-up contributions and Roth conversions.", retiree="Plan withdrawals, conversions, and required distributions.", legacy="Coordinate gifts, step-up in basis, and estate plans."),
 example="Yolanda wants to give $20,000 to her church this year. Instead of writing a check, she donates shares she bought years ago for $8,000 that are now worth $20,000. If she itemizes, she may deduct the full $20,000 (subject to limits) and avoids capital gains tax on the $12,000 of growth, while her church receives the full value. (Hypothetical example; consult a tax professional.)",
 terms=[["Asset location", "Placing investments in the accounts where they are taxed best."], ["Roth conversion", "Moving money from a traditional to a Roth account, paying tax now."], ["Donor-advised fund", "A charitable account that lets you give now and grant later."], ["Annual exclusion", "The amount you can give each person yearly without using your exemption."], ["Estate tax exemption", "The amount that can pass free of federal estate tax."], ["Step-up in basis", "Resetting an inherited asset's cost basis to its value at death."]],
 verse=["Render therefore unto Caesar the things which are Caesar's; and unto God the things that are God's.", "Matthew 22:21"],
 check=["Map which investments sit in which accounts", "Ask your CPA about a year-end tax projection", "List appreciated investments you could give", "Review your annual gifting plan"],
 quiz=[
  dict(q="Asset location means:", o=["Placing investments in the accounts where they are taxed best", "Choosing a bank branch", "Buying property"], a=0, why="Where you hold investments matters."),
  dict(q="A Roth conversion means:", o=["Paying tax now so future qualified withdrawals are tax-free", "Avoiding all tax", "Closing an IRA"], a=0, why="Often considered in lower-income years."),
  dict(q="Giving appreciated stock held over a year can:", o=["Avoid capital gains tax on the growth", "Increase your taxes", "Be illegal"], a=0, why="And may allow a full deduction, subject to limits."),
  dict(q="In 2026, the annual gift exclusion is:", o=["$19,000 per person", "$1,000", "Unlimited"], a=0, why="Gifts within it do not use your lifetime exemption."),
  dict(q="In 2026, the federal estate and gift tax exemption is:", o=["$15 million per person", "$100,000", "$1 billion"], a=0, why="Verify current law each year."),
  dict(q="A step-up in basis:", o=["Resets an inherited asset's basis to its value at death", "Raises taxes", "Applies only to cash"], a=0, why="It can erase built-up gains."),
  dict(q="Tax-inefficient investments, like bonds, are often held in:", o=["Tax-deferred accounts", "Taxable accounts", "Cash only"], a=0, why="Their income is taxed as ordinary income."),
  dict(q="A year-end tax projection helps because:", o=["Some strategies end December 31", "It is required by law", "It replaces your return"], a=0, why="Plan before the year closes."),
  dict(q="Aggressive tax shelters sold by promoters are:", o=["A warning sign", "Always legal", "Required"], a=0, why="Use qualified professionals."),
  dict(q="Matthew 22:21 teaches us to:", o=["Render unto Caesar what is Caesar's", "Avoid taxes illegally", "Ignore taxes"], a=0, why="Pay what you owe; steward the rest."),
 ])

L['kingdom-2'] = dict(deep=True, mins=14,
 intro="Trusts are among the most important tools for protecting and passing on wealth. A trust is a legal arrangement in which one person or institution, the trustee, holds and manages assets for the benefit of others, the beneficiaries. Understanding the difference between revocable and irrevocable trusts helps you choose wisely with your attorney.",
 connect="Trusts carry your values and your care into the next generation.",
 sections=[
  ["The parts of a trust", ["The grantor creates the trust and transfers assets into it. The trustee manages the assets according to the trust's terms. The beneficiaries receive the benefits. The trust document spells out the rules: who receives what, when, and under what conditions."]],
  ["Revocable living trusts", ["A revocable trust can be changed or ended by the grantor during life. The grantor usually serves as trustee, keeping full control. It can help avoid probate in many states, keep matters private, and provide for management if the grantor becomes incapacitated. It generally does not reduce estate taxes or protect assets from the grantor's creditors."]],
  ["Irrevocable trusts", ["An irrevocable trust generally cannot be changed easily once created. In exchange for giving up control, it can remove assets from the taxable estate, protect assets from certain creditors, and support specific goals. Examples include irrevocable life insurance trusts, charitable trusts, and trusts for a loved one with special needs."]],
  ["Funding the trust", ["A trust only governs assets placed in it. Retitling accounts and property into the trust's name, and coordinating beneficiary designations, is essential. An unfunded trust is one of the most common estate planning mistakes."]],
  ["Choosing trustees with care", ["Choose trustees who are trustworthy, capable, and willing. Many families name a successor trustee or a professional corporate trustee.",
    "\"Moreover it is required in stewards, that a man be found faithful\" (1 Corinthians 4:2)."]],
 ],
 pros=["Can avoid probate and keep matters private", "Provides management if you become incapacitated", "Can protect beneficiaries and carry your values", "Irrevocable trusts can reduce estate taxes"],
 cons=["Trusts cost money to create and administer", "Irrevocable trusts limit your control", "Trusts must be funded to work", "Laws vary by state"],
 watch=["Work with a licensed estate planning attorney in your state.", "Fund your trust; retitle assets and coordinate beneficiaries.", "Be wary of \"trust mills\" selling one-size-fits-all documents.", "Review your trust after major life changes."],
 tip="After signing a trust, make a funding checklist: every bank account, brokerage account, and property, with a column for \"retitled\" and the date. Bring it to your attorney to confirm nothing was missed.",
 fit=dict(starter="A will and beneficiary designations may be enough for now.", mom="A trust can provide for minor children with your guidance built in.", rebuilder="Update or create your trust after divorce or loss.", ent="Consider how your business interests will pass through a trust.", exec="Coordinate equity awards and accounts with your trust.", late="A revocable trust can simplify matters for your family.", retiree="Plan for incapacity and successor trustees.", legacy="Irrevocable and charitable trusts can carry your legacy further."),
 example="Sharon creates a revocable living trust, retitles her home and brokerage account into it, and names her sister as successor trustee. When Sharon later has surgery and cannot manage her affairs for several months, her sister steps in smoothly, without court involvement. Her trust also directs that her nieces receive their inheritance in stages, with funds for education first. (Hypothetical example.)",
 terms=[["Grantor", "The person who creates and funds a trust."], ["Trustee", "The person or institution managing the trust."], ["Beneficiary", "The person who receives benefits from the trust."], ["Revocable trust", "A trust the grantor can change during life."], ["Irrevocable trust", "A trust that generally cannot be easily changed."], ["Funding", "Transferring assets into the trust's name."]],
 verse=["Moreover it is required in stewards, that a man be found faithful.", "1 Corinthians 4:2"],
 check=["List assets you would place in a trust", "Identify a trustworthy successor trustee", "Write questions for an estate planning attorney", "Review all beneficiary designations"],
 quiz=[
  dict(q="The trustee:", o=["Manages trust assets", "Only receives benefits", "Creates the trust"], a=0, why="The grantor creates; the trustee manages."),
  dict(q="A revocable trust:", o=["Can be changed by the grantor during life", "Can never be changed", "Avoids all taxes"], a=0, why="The grantor keeps control."),
  dict(q="A revocable trust generally does NOT:", o=["Reduce estate taxes", "Avoid probate in many states", "Plan for incapacity"], a=0, why="Irrevocable trusts serve that purpose."),
  dict(q="An irrevocable trust can:", o=["Remove assets from the taxable estate", "Be changed at will", "Avoid all rules"], a=0, why="In exchange for giving up control."),
  dict(q="A common estate planning mistake is:", o=["Failing to fund the trust", "Naming a trustee", "Using an attorney"], a=0, why="A trust governs only assets placed in it."),
  dict(q="The grantor is:", o=["The person who creates and funds the trust", "The beneficiary", "The court"], a=0, why="She sets the terms."),
  dict(q="Trusts can provide for:", o=["Management if you become incapacitated", "Only death", "Nothing"], a=0, why="They protect you during life too."),
  dict(q="\"Trust mills\" selling one-size-fits-all documents are:", o=["A warning sign", "Best practice", "Required"], a=0, why="Work with a licensed attorney."),
  dict(q="Trust laws:", o=["Vary by state", "Are identical nationwide", "Do not exist"], a=0, why="Local counsel matters."),
  dict(q="1 Corinthians 4:2 says stewards must be:", o=["Found faithful", "Famous", "Wealthy"], a=0, why="Choose faithful trustees."),
 ])

