 terms=[["LLC", "Limited liability company, a flexible business entity."], ["S corporation", "A tax election that passes income through to owners."], ["C corporation", "A corporation taxed separately from its owners."], ["Series LLC", "An LLC with separate series that can hold separate assets."], ["Holding company", "An entity that owns other businesses or assets."], ["Succession plan", "A plan for transferring leadership and ownership."]],
