  dict(q="Family meetings build:", o=["Communication and trust", "Conflict", "Secrecy"], a=0, why="Regular gatherings strengthen unity."),
  dict(q="Preparing heirs includes:", o=["Teaching skills and giving responsibility gradually", "Giving everything at once", "Avoiding money talks"], a=0, why="Wisdom must accompany wealth."),
  dict(q="Staged distributions:", o=["Give an inheritance in parts over time", "Give it all at once", "Avoid inheritance"], a=0, why="They allow growth in wisdom."),
  dict(q="A neutral facilitator can help with:", o=["Difficult conversations", "Picking stocks", "Taxes only"], a=0, why="Neutrality eases tension."),
  dict(q="A warm first family meeting topic is:", o=["Shared giving", "Detailed balances", "Disputes"], a=0, why="Generosity opens doors."),
  dict(q="The greatest inheritance is often:", o=["Values, faith, and wisdom", "Only money", "Property alone"], a=0, why="Character outlasts assets."),
  dict(q="Information shared with family should be:", o=["Age-appropriate and thoughtful", "Everything immediately", "Nothing ever"], a=0, why="Share with care."),
